"""PDF108 printed 207–208: Example 6.7 efficiency comparison; 6.2.5 pooled estimators; Example 6.8 pooled mean, variance and proportion."""
from class12_statistics_common import Builder, save

SOL = ('Solution:', 'حل:', 'حل:')
T1, T2 = r'\hat{\theta}_1', r'\hat{\theta}_2'
b = Builder()
b.mlines([r'=\frac{1}{9}[Var(X_1)+Var(X_2)+Var(X_3)]', r'=\frac{1}{9}[\sigma^2+\sigma^2+\sigma^2]=\sigma^2/3'])
b.p(f'Now compare the efficiency of ${T1}$ relative to ${T2}$ as;', f'اب ${T1}$ کی کارکردگی کا ${T2}$ کے مقابلے میں یوں موازنہ کریں؛', f'اوس د ${T1}$ موثریت د ${T2}$ په پرتله داسې پرتله کړئ؛')
b.p(f'$R.E=\\frac{{V({T1})}}{{V({T2})}}=\\frac{{3\\sigma^2/8}}{{\\sigma^2/3}}=\\frac{{3\\sigma^2}}{{8}}\\times\\frac{{3}}{{\\sigma^2}}=\\frac{{9}}{{8}}=1.125>1\\Rightarrow{T2}$ is efficient than ${T1}$', f'$R.E=\\frac{{V({T1})}}{{V({T2})}}=\\frac{{3\\sigma^2/8}}{{\\sigma^2/3}}=\\frac{{3\\sigma^2}}{{8}}\\times\\frac{{3}}{{\\sigma^2}}=\\frac{{9}}{{8}}=1.125>1\\Rightarrow{T2}$، ${T1}$ سے زیادہ مؤثر ہے', f'$R.E=\\frac{{V({T1})}}{{V({T2})}}=\\frac{{3\\sigma^2/8}}{{\\sigma^2/3}}=\\frac{{3\\sigma^2}}{{8}}\\times\\frac{{3}}{{\\sigma^2}}=\\frac{{9}}{{8}}=1.125>1\\Rightarrow{T2}$ تر ${T1}$ موثر دی')
b.p(f'Thus relative efficiency criteria shows that the estimator ${T2}$ is efficient than ${T1}$. It means that $var({T2})<var({T1})$ and hence ${T2}$ is the best estimator for the parameter μ.', f'لہٰذا نسبتی کارکردگی کا معیار ظاہر کرتا ہے کہ تخمین کار ${T2}$، ${T1}$ سے زیادہ مؤثر ہے۔ اس کا مطلب ہے کہ $var({T2})<var({T1})$ اور لہٰذا ${T2}$ پیرامیٹر μ کا بہترین تخمین کار ہے۔', f'نو د نسبي موثریت معیار ښيي چې اټکلوونکی ${T2}$ تر ${T1}$ موثر دی. مانا یې دا ده چې $var({T2})<var({T1})$ او نو ${T2}$ د μ پارامټر لپاره غوره اټکلوونکی دی.')
ex7 = b.build('stat12-p108-example-6-7-efficiency', 'Example 6.7 — efficiency comparison', 'مثال 6.7 — کارکردگی کا موازنہ', 'بېلګه 6.7 — د موثریت پرتله', 108, [207])
issues = [{'id': 'stat12-p207-ex67-conclusion', 'unit': 6, 'printedPage': 207, 'description': 'Example 6.7(ii) asks to show θ̂₁ is more efficient than θ̂₂, but the printed solution (correctly) concludes θ̂₂ is more efficient (R.E = 1.125). Question and solution kept as printed.'}]

c = Builder()
c.h('6.2.5 Pooled estimator from two samples', '6.2.5 دو نمونوں سے مشترکہ (pooled) تخمین کار', '6.2.5 له دوو نمونو څخه ګډ (pooled) اټکلوونکی')
c.p('Parameters can also be estimated by estimators which are obtained by pooling (combining) the estimators computed from two or more random samples drawn from the same population, such an estimator is called pooled estimator. For example two random samples of sizes $n_1$ and $n_2$ have means $\\overline{x}_1,\\overline{x}_2$ and variances $s_1^2,s_2^2$ respectively, then combined mean given as $\\overline{x}_c=\\frac{n_1\\overline{x}_1+n_2\\overline{x}_2}{n_1+n_2}$ is pooled estimator of μ and combined variance $s_p^2=\\frac{(n_1-1)s_1^2+(n_2-1)s_2^2}{n_1+n_2-2}$ is pooled variance estimate of $\\sigma^2$. Similarly, if random samples of sizes $n_1,n_2$ are drawn from a binomial population having sample proportions $\\hat{p}_1,\\hat{p}_2$, then $\\hat{p}_c=\\frac{n_1\\hat{p}_1+n_2\\hat{p}_2}{n_1+n_2}$ is pooled estimator for p. If needed, pooled estimators from 3 or more samples can be obtained to extend in a similar way.',
    'پیرامیٹرز کا تخمین ایسے تخمین کاروں سے بھی لگایا جا سکتا ہے جو ایک ہی آبادی سے نکالے گئے دو یا زیادہ تصادفی نمونوں سے معلوم کیے گئے تخمین کاروں کو ملا کر (یکجا کر کے) حاصل کیے جائیں، ایسے تخمین کار کو مشترکہ (pooled) تخمین کار کہتے ہیں۔ مثلاً $n_1$ اور $n_2$ سائز کے دو تصادفی نمونوں کے اوسط بالترتیب $\\overline{x}_1,\\overline{x}_2$ اور تغیرات $s_1^2,s_2^2$ ہوں تو مجموعی اوسط $\\overline{x}_c=\\frac{n_1\\overline{x}_1+n_2\\overline{x}_2}{n_1+n_2}$، μ کا مشترکہ تخمین کار ہے اور مجموعی تغیر $s_p^2=\\frac{(n_1-1)s_1^2+(n_2-1)s_2^2}{n_1+n_2-2}$، $\\sigma^2$ کا مشترکہ تغیر کا تخمینہ ہے۔ اسی طرح اگر $n_1,n_2$ سائز کے تصادفی نمونے دو رقمی آبادی سے نکالے جائیں جن کے نمونہ جاتی تناسب $\\hat{p}_1,\\hat{p}_2$ ہوں تو $\\hat{p}_c=\\frac{n_1\\hat{p}_1+n_2\\hat{p}_2}{n_1+n_2}$، p کا مشترکہ تخمین کار ہے۔ اگر ضرورت ہو تو 3 یا زیادہ نمونوں سے مشترکہ تخمین کار اسی طرح حاصل کیے جا سکتے ہیں۔',
    'پارامټرونه د داسې اټکلوونکو په واسطه هم اټکل کېدای شي چې له یوه نفوس څخه د راایستل شویو دوو یا ډېرو تصادفي نمونو څخه د محاسبه شویو اټکلوونکو په یوځای کولو ترلاسه شي، داسې اټکلوونکي ته ګډ (pooled) اټکلوونکی وایي. د بېلګې په توګه که د $n_1$ او $n_2$ اندازې دوه تصادفي نمونې په ترتیب سره منځني $\\overline{x}_1,\\overline{x}_2$ او واریانسونه $s_1^2,s_2^2$ ولري، نو ګډ منځنی $\\overline{x}_c=\\frac{n_1\\overline{x}_1+n_2\\overline{x}_2}{n_1+n_2}$ د μ ګډ اټکلوونکی دی او ګډ واریانس $s_p^2=\\frac{(n_1-1)s_1^2+(n_2-1)s_2^2}{n_1+n_2-2}$ د $\\sigma^2$ د ګډ واریانس اټکل دی. همداراز که د $n_1,n_2$ اندازې تصادفي نمونې له بینومیل نفوس څخه راایستل شي چې نمونوي تناسبونه یې $\\hat{p}_1,\\hat{p}_2$ وي، نو $\\hat{p}_c=\\frac{n_1\\hat{p}_1+n_2\\hat{p}_2}{n_1+n_2}$ د p ګډ اټکلوونکی دی. که اړتیا وي، له 3 یا ډېرو نمونو ګډ اټکلوونکي په ورته ډول ترلاسه کېدای شي.')
c.h('Example 6.8', 'مثال 6.8', 'بېلګه 6.8')
c.p('Consider the following two samples', 'درج ذیل دو نمونوں پر غور کریں', 'لاندې دوه نمونې په پام کې ونیسئ')
c.table('stat12-t-ex6-8', ['', '', '', '', ''], [['Sample A:', '1', '4', '8', '5'], ['Sample B:', '3', '0', '9', '4']], ['', '', '', '', ''], ['', '', '', '', ''],
        [['نمونہ A:', '1', '4', '8', '5'], ['نمونہ B:', '3', '0', '9', '4']], [['نمونه A:', '1', '4', '8', '5'], ['نمونه B:', '3', '0', '9', '4']], noHeader=True)
c.p('Compute pooled estimate for (i) population mean μ (ii) population variance $\\sigma^2$ and (iii) proportion of odd numbers in the population.', 'مشترکہ تخمینہ معلوم کریں (i) آبادی کا اوسط μ (ii) آبادی کا تغیر $\\sigma^2$ اور (iii) آبادی میں طاق اعداد کا تناسب۔', 'ګډ اټکل یې محاسبه کړئ (i) د نفوس منځنی μ (ii) د نفوس واریانس $\\sigma^2$ او (iii) په نفوس کې د طاق عددونو تناسب.')
c.h(*SOL)
c.mlines([r'(i)\quad\overline{x}_1=\frac{1+4+8+5}{4}=\frac{18}{4}=4.5\qquad\overline{x}_2=\frac{3+0+9+4}{4}=\frac{16}{4}=4'])
c.p('$\\therefore\\ \\overline{x}_c=\\frac{n_1\\overline{x}_1+n_2\\overline{x}_2}{n_1+n_2}=\\frac{4(4.5)+4(4)}{4+4}=\\frac{18+16}{8}=\\frac{34}{8}=4.25$ is the pooled estimate of μ.', '$\\therefore\\ \\overline{x}_c=\\frac{n_1\\overline{x}_1+n_2\\overline{x}_2}{n_1+n_2}=\\frac{4(4.5)+4(4)}{4+4}=\\frac{18+16}{8}=\\frac{34}{8}=4.25$، μ کا مشترکہ تخمینہ ہے۔', '$\\therefore\\ \\overline{x}_c=\\frac{n_1\\overline{x}_1+n_2\\overline{x}_2}{n_1+n_2}=\\frac{4(4.5)+4(4)}{4+4}=\\frac{18+16}{8}=\\frac{34}{8}=4.25$ د μ ګډ اټکل دی.')
c.mlines([r'(ii)\quad s_1^2=\frac{1}{n_1-1}\left[\Sigma x_1^2-\frac{(\Sigma x_1)^2}{n_1}\right]=\frac{1}{4-1}\left[106-\frac{(18)^2}{4}\right]=\frac{1}{3}[25]=8.333',
          r's_2^2=\frac{1}{n_{2-1}}\left[\Sigma x_2^2-\frac{(\Sigma x_2)^2}{n_2}\right]=\frac{1}{4-1}\left[106-\frac{(16)^2}{4}\right]=\frac{1}{3}[42]=14',
          r'\therefore s_p^2=\frac{(n_1-1)s_1^2+(n_2-1)s_2^2}{n_1+n_2-2}=\frac{(4-1)(8.333)+(4-1)(14)}{4+4-2}'])
c.p('$=\\frac{24.999+42}{6}=\\frac{66.999}{6}=11.17$ is the pooled estimate of $\\sigma^2$.', '$=\\frac{24.999+42}{6}=\\frac{66.999}{6}=11.17$، $\\sigma^2$ کا مشترکہ تخمینہ ہے۔', '$=\\frac{24.999+42}{6}=\\frac{66.999}{6}=11.17$ د $\\sigma^2$ ګډ اټکل دی.')
c.p('(iii) Proportion of odd numbers in sample A: $\\hat{p}_1=\\frac{2}{4}=0.5$', '(iii) نمونہ A میں طاق اعداد کا تناسب: $\\hat{p}_1=\\frac{2}{4}=0.5$', '(iii) په A نمونه کې د طاق عددونو تناسب: $\\hat{p}_1=\\frac{2}{4}=0.5$')
c.p('Proportion of odd numbers in sample B: $\\hat{p}_2=\\frac{2}{4}=0.5$', 'نمونہ B میں طاق اعداد کا تناسب: $\\hat{p}_2=\\frac{2}{4}=0.5$', 'په B نمونه کې د طاق عددونو تناسب: $\\hat{p}_2=\\frac{2}{4}=0.5$')
c.p('$\\therefore\\ \\hat{p}_c=\\frac{n_1\\hat{p}_1+n_2\\hat{p}_2}{n_1+n_2}=\\frac{4(0.5)+4(0.5)}{4+4}=\\frac{2+2}{8}=0.5$ is the pooled estimate of p.', '$\\therefore\\ \\hat{p}_c=\\frac{n_1\\hat{p}_1+n_2\\hat{p}_2}{n_1+n_2}=\\frac{4(0.5)+4(0.5)}{4+4}=\\frac{2+2}{8}=0.5$، p کا مشترکہ تخمینہ ہے۔', '$\\therefore\\ \\hat{p}_c=\\frac{n_1\\hat{p}_1+n_2\\hat{p}_2}{n_1+n_2}=\\frac{4(0.5)+4(0.5)}{4+4}=\\frac{2+2}{8}=0.5$ د p ګډ اټکل دی.')
pool = c.build('stat12-p108-pooled', '6.2.5 Pooled estimators — Example 6.8', '6.2.5 مشترکہ تخمین کار — مثال 6.8', '6.2.5 ګډ اټکلوونکي — بېلګه 6.8', 108, [207, 208])
issues.append({'id': 'stat12-p208-ex68-sx1sq', 'unit': 6, 'printedPage': 208, 'description': 'Example 6.8 prints Σx₁² = 106 for sample A (actual 1+16+64+25 = 106 ✓) and also Σx₂² = 106 for sample B (actual 9+0+81+16 = 106 ✓); the denominator of s₂² is printed “n_{2−1}”. Printed forms retained.'})

